/* -------------- */ /* Sale Outlier Users have on of the conditions below: */ /* 1 - More than 15 visits booked in the past 30 days */ /* 2 - More than 3 offers submitted in the past 30 days */ /* These values were obtained by 1) looking at the current distribution and 2) somewhat intuition into what "normal" users can do */ WITH sale_user_metrics AS (SELECT id_buyer AS id_user, COUNT(DISTINCT CASE WHEN NOT ts_first_booking_created IS NULL THEN id_house END) AS total_bookings, COUNT(DISTINCT CASE WHEN NOT ts_first_offer_submitted IS NULL THEN id_house END) AS total_offers FROM datalake_sale_flows.sale_flow WHERE NOT id_buyer IS NULL AND NOT id_house IS NULL AND (ts_first_booking_created BETWEEN DATE_ADD(CAST('{start_date}' AS DATE), STRUCT(days_past_30 AS days_past_30) * -1) AND CAST('{end_date}' AS DATE) OR ts_first_offer_submitted BETWEEN DATE_ADD(CAST('{start_date}' AS DATE), STRUCT(days_past_30 AS days_past_30) * -1) AND CAST('{end_date}' AS DATE)) GROUP BY id_buyer) SELECT id_user, total_bookings, total_offers FROM sale_user_metrics WHERE total_bookings >= 15 OR total_offers >= 3